### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int sum = 0, x;
    for (int i = 0; i < 5; ++i) {                        // 五部分加起来就是咕值
        cin >> x;
        sum += x;
    }

    if (sum < 100) cout << "Grey\n";                     // 0 ~ 99
    else if (sum < 120) cout << "Blue\n";                // 100 ~ 119
    else if (sum < 170) cout << "Green\n";               // 120 ~ 169
    else if (sum < 230) cout << "Orange\n";              // 170 ~ 229
    else cout << "Red\n";                                // 230 ~ 500
    return 0;
}
```

### 易错点

用互斥的 if / else if，总分恰好为 $100,120,170,230$ 时进入下一档。

