### 参考代码

```cpp
// B. 礼堂预约 II
// 题意：活动从 a:00 开始、到 b:00 结束，判断它是否完整落在某一个规定时段内：
//       上午 M = 8:00~12:00、下午 A = 13:00~17:00、晚上 E = 18:00~21:00；
//       落在空隙里、跨时段、落在时段外，都输出 F。允许不用完整个时段。
// 做法：三个时段各写一次区间包含判断（另外要求 a <= b，防止开始晚于结束）。
#include <bits/stdc++.h>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;                               // 开始 a:00，结束 b:00
    if (a <= b && a >= 8 && b <= 12)       cout << "M\n";   // 完整落在上午
    else if (a <= b && a >= 13 && b <= 17) cout << "A\n";   // 完整落在下午
    else if (a <= b && a >= 18 && b <= 21) cout << "E\n";   // 完整落在晚上
    else                                   cout << "F\n";   // 跨时段 / 空隙 / 时段外
    return 0;
}
```

